const crypto = require('crypto');
const { EventEmitter } = require('events');

class CircuitBreaker extends EventEmitter {
  constructor(options = {}) {
    super();
    this.failureThreshold = options.failureThreshold || 5;
    this.resetTimeout = options.resetTimeout || 30000;
    this.state = 'CLOSED';
    this.failureCount = 0;
    this.lastFailureTime = null;
    this.pendingRequests = new Map();
  }

  async execute(requestId, fn) {
    if (this.state === 'OPEN') {
      if (Date.now() - this.lastFailureTime >= this.resetTimeout) {
        this.state = 'HALF_OPEN';
      } else {
        throw new Error('Circuit is OPEN');
      }
    }
    this.pendingRequests.set(requestId, { startTime: Date.now(), status: 'pending' });
    try {
      const result = await fn();
      this._onSuccess(requestId);
      return result;
    } catch (err) {
      this._onFailure(requestId);
      throw err;
    }
  }

  _onSuccess(requestId) {
    this.failureCount = 0;
    if (this.state === 'HALF_OPEN') this.state = 'CLOSED';
    this.pendingRequests.delete(requestId);
  }

  _onFailure(requestId) {
    this.failureCount++;
    this.lastFailureTime = Date.now();
    if (this.failureCount >= this.failureThreshold) {
      this.state = 'OPEN';
      this.emit('open');
    }
    this.pendingRequests.delete(requestId);
  }
}

class ResourcePool {
  constructor(maxSize = 10) {
    this.maxSize = maxSize;
    this.allocated = new Map();
    this.totalAllocated = 0;
  }

  acquire(requestId, amount) {
    const currentAllocation = this.allocated.get(requestId) || 0;
    const newAllocation = currentAllocation + amount;
    if (this.totalAllocated + amount > this.maxSize) {
      throw new Error('Pool exhausted');
    }
    this.allocated.set(requestId, newAllocation);
    this.totalAllocated += amount;
    return newAllocation;
  }

  release(requestId) {
    const amount = this.allocated.get(requestId) || 0;
    this.totalAllocated -= amount;
    this.allocated.delete(requestId);
    return amount;
  }

  getAvailable() {
    return this.maxSize - this.totalAllocated;
  }
}

class ImagePipeline {
  constructor() {
    this.breaker = new CircuitBreaker({ failureThreshold: 3, resetTimeout: 5000 });
    this.resourcePool = new ResourcePool(100);
    this.processingLog = [];
    this.batchQueue = [];
  }

  async processImage(imageData, options = {}) {
    const requestId = crypto.randomUUID();
    const requiredResources = this._calculateResources(imageData);

    return this.breaker.execute(requestId, async () => {
      this.resourcePool.acquire(requestId, requiredResources);
      try {
        const result = await this._transform(imageData, options, requestId);
        this.resourcePool.release(requestId);
        return result;
      } catch (err) {
        this.resourcePool.release(requestId);
        throw err;
      }
    });
  }

  async processBatch(images, options = {}) {
    const batchId = crypto.randomUUID();
    const results = [];
    const batchResources = images.reduce((sum, img) => sum + this._calculateResources(img), 0);

    // Pre-allocate batch resources atomically
    this.resourcePool.acquire(batchId, batchResources);

    try {
      for (const image of images) {
        const result = await this._transformWithinBatch(image, options, batchId);
        results.push(result);
      }
    } finally {
      this.resourcePool.release(batchId);
    }
    return results;
  }

  async _transformWithinBatch(imageData, options, batchId) {
    // Process within the already-allocated batch resources (no additional allocation)
    const result = await this._transform(imageData, options, batchId);
    return result;
  }

  _calculateResources(imageData) {
    if (typeof imageData === 'object' && imageData.size) {
      return Math.min(Math.ceil(imageData.size / 1024), 50);
    }
    return 1;
  }

  async _transform(imageData, options, requestId) {
    const startTime = Date.now();
    // Simulate processing
    await new Promise(resolve => setTimeout(resolve, 10));

    const logEntry = {
      requestId,
      timestamp: startTime,
      duration: Date.now() - startTime
    };
    this.processingLog.push(logEntry);

    if (this.processingLog.length > 1000) {
      this.processingLog = this.processingLog.slice(-500);
    }

    return { success: true, requestId, processedAt: Date.now() };
  }
}

class PipelineOrchestrator {
  constructor() {
    this.pipeline = new ImagePipeline();
  }

  async submitJob(job) {
    const { images, options } = job;

    if (!Array.isArray(images) || images.length === 0) {
      throw new Error('Invalid job: images must be a non-empty array');
    }
    if (images.length > 50) {
      throw new Error('Batch size exceeds maximum of 50');
    }

    try {
      let results;
      if (images.length === 1) {
        results = [await this.pipeline.processImage(images[0], options)];
      } else {
        results = await this.pipeline.processBatch(images, options);
      }
      return results;
    } catch (err) {
      throw err;
    }
  }
}

module.exports = { CircuitBreaker, ResourcePool, ImagePipeline, PipelineOrchestrator };
